<?php
declare(strict_types=1);
$videos = is_array($videos ?? null) ? $videos : [];
?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Videos</h1><p class="text-muted mb-0">Administra la biblioteca y su orden de aparición.</p></div><a class="btn btn-primary" href="<?= e(url('admin/videos/nuevo')) ?>"><i class="bi bi-plus-lg me-1"></i>Nuevo video</a></div><div class="admin-card card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Video</th><th>Origen</th><th>Duración</th><th>Reproducciones</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php foreach ($videos as $video): ?><tr><td><strong><?= e((string) $video['title']) ?></strong><br><small class="text-muted">/<?= e((string) $video['slug']) ?></small></td><td><?= e((string) $video['source']) ?></td><td><?= (int) $video['duration_seconds'] > 0 ? e((string) floor((int) $video['duration_seconds'] / 60) . ':' . str_pad((string) ((int) $video['duration_seconds'] % 60), 2, '0', STR_PAD_LEFT)) : '-' ?></td><td><?= (int) $video['view_count'] ?></td><td><?= ($video['status'] ?? '') === 'active' ? 'Visible' : 'Oculto' ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/videos/' . (int) $video['id'] . '/editar')) ?>">Editar</a><form method="post" action="<?= e(url('admin/videos/' . (int) $video['id'])) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger" type="submit" onclick="return confirm('El video dejará de verse en la web. No se borra: podrás recuperarlo durante 30 días. ¿Continuar?');">Papelera</button></form></td></tr><?php endforeach; ?><?php if ($videos === []): ?><tr><td colspan="6" class="text-center py-4">Todavía no hay videos.</td></tr><?php endif; ?></tbody></table></div></div>